<?php
/**
 * Translation helpers.
 *
 * UI strings use the English text as the key with {placeholders} — the same
 * keys as the prototype's locale files, so the existing translations are reused
 * as-is (languages/egypt-roamer-{locale}.l10n.php, generated by
 * tools/build-translations.mjs).
 */

defined( 'ABSPATH' ) || exit;

add_action( 'after_setup_theme', static function () {
	load_theme_textdomain( 'egypt-roamer', ER_THEME_DIR . '/languages' );
} );

/** Translate a UI string and fill {placeholders}. Returns unescaped text. */
function er_t( string $text, array $vars = [] ): string {
	$out = translate( $text, 'egypt-roamer' ); // phpcs:ignore WordPress.WP.I18n -- keys are shared with the JS dictionaries
	if ( $vars ) {
		$map = [];
		foreach ( $vars as $k => $v ) {
			$map[ '{' . $k . '}' ] = (string) $v;
		}
		$out = strtr( $out, $map );
	}
	return $out;
}

/**
 * A UI string only when this language has a real translation for it, else null (never the
 * English source on a translated page). English returns the text itself.
 */
function er_t_strict( string $text ): ?string {
	if ( 'en' === er_lang() ) {
		return $text;
	}
	$out = class_exists( 'WP_Translation_Controller' ) ? WP_Translation_Controller::get_instance()->translate( $text, '', 'egypt-roamer' ) : false;
	return false === $out || '' === $out ? null : (string) $out;
}

/** Echo an escaped UI string. */
function er_e( string $text, array $vars = [] ): void {
	echo esc_html( er_t( $text, $vars ) );
}

/** The "go on" arrow after a link or button label: it points the way the text reads (left in Arabic). */
function er_arrow(): string {
	return 'ar' === er_lang() ? '←' : '→';
}

/**
 * Arabic pages: a number range such as "4–10" is laid out right to left by the browser's bidi rules and
 * reads "10–4" (owner, 28 Oct: trip chips and guide bodies). Each range in the page text is wrapped in a
 * left-to-right isolate (U+2066 … U+2069), so it keeps its order inside the Arabic sentence. Text only:
 * tags, attributes, scripts and styles are left as they are. The same pass keeps " · " separators with the word before them.
 */
function er_isolate_ranges( string $html ): string {
	$ar    = 'ar' === er_lang();
	$parts = preg_split( '#(<script\b.*?</script>|<style\b.*?</style>|<textarea\b.*?</textarea>|<[^>]*>)#si', $html, -1, PREG_SPLIT_DELIM_CAPTURE );
	if ( ! is_array( $parts ) ) {
		return $html;
	}
	foreach ( $parts as $i => $part ) {
		if ( '' !== $part && '<' !== $part[0] ) {
			if ( $ar ) {
				// Decimals stay inside the isolate: "1.5–3" once showed as "3.1–5" (owner's balloon page, 28 Oct).
				$part = (string) preg_replace( '/(?<![\d.\x{2066}])(\d+(?:\.\d+)?\s?–\s?\d+(?:\.\d+)?)(?![\d\x{2069}])/u', "\u{2066}$1\u{2069}", $part );
			}
			// Every language: the " · " separator in card lines keeps to the word before it, so a wrapped line never
			// starts or ends with a lone dot (owner, 28 Oct, the Arabic trip cards).
			$parts[ $i ] = str_replace( ' · ', "\u{00A0}· ", $part );
		}
	}
	return implode( '', $parts );
}
add_action( 'template_redirect', static function (): void {
	if ( ! is_admin() && ! is_feed() ) {
		ob_start( 'er_isolate_ranges' );
	}
} );

/** Current language slug (Polylang when active). */
function er_lang(): string {
	return function_exists( 'er_current_lang' ) ? er_current_lang() : substr( determine_locale(), 0, 2 );
}

/**
 * Complianz has no Russian, Chinese or Arabic language pack, so the one fixed label its cookie banner shows
 * ("Always active", next to Functional) stays English there. The banner's own texts are translated
 * in Polylang → Strings translations (group "complianz"); de/fr/it/es get this label from Complianz.
 */
add_filter( 'gettext_complianz-gdpr', static function ( string $translation, string $text ): string {
	if ( 'Always active' !== $text || $translation !== $text ) {
		return $translation;
	}
	return [ 'ru' => 'Всегда активно', 'zh' => '始终启用', 'ar' => 'مفعّلة دائمًا' ][ er_lang() ] ?? $translation;
}, 10, 2 );

/**
 * The current language's homepage (/, /de/, /ar/ …). Explicit rather than home_url( '/' ), which
 * Polylang localises only by matching the caller's file path against the theme folder.
 */
function er_home_url(): string {
	$url = function_exists( 'pll_home_url' ) ? (string) pll_home_url() : '';
	return trailingslashit( '' !== $url ? $url : home_url( '/' ) );
}

/** Languages the interface JavaScript has dictionaries for. */
function er_js_languages(): array {
	return [ 'en', 'de', 'fr', 'it', 'es', 'ru', 'zh', 'ar' ];
}
